    context.strokeStyle = PALETTE.roadLine;
    context.lineWidth = 4;
    context.setLineDash([40, 40]);
    for (let gx = 0; gx <= bx; gx += 1) {
      const x = ox + gx * (bw + rw);
      context.beginPath();
      context.moveTo(x, 0);
      context.lineTo(x, FIELD.height);
      context.stroke();
    }
    for (let gy = 0; gy <= by; gy += 1) {
